# # Practice 
# # Q1 — Revenue Contribution Calculate: Total revenue, Each customer's Revenue_%, Verify that Revenue_% sums to 100%
# # Q2 — Cumulative Revenue Sort customers from highest to lowest sales. Create: Cumulative_Revenue_% Find the customer at which cumulative revenue first reaches or exceeds 80%.
# # Q3 — Pareto Customers Create a Pareto_Group: Top 80% Revenue Contributors, emaining Customers. Then calculate how many customers belong to each group.
# # Q4 — Revenue Concentration Calculate: Revenue generated by the top 3 customers, Percentage of total revenue generated by top 3, Revenue generated by remaining customers
# # Q5 — Profit Concentration Repeat the analysis using Profit: Sort by Total Profit, Profit %, Cumulative Profit %, Identify customers contributing to the majority of profit
import pandas as pd
import numpy as np

df = pd.DataFrame({
    "Customer": [
        "Amit","Riya","Rahul","Priya",
        "Karan","Neha","Vikram","Anu"
    ],
    "Total_Sales": [
        180000,140000,85000,120000,
        30000,25000,95000,65000
    ],
    "Total_Profit": [
        36000,28000,17000,24000,
        6000,5000,19000,13000
    ]
})
# Total revenue
total_revenue = df["Total_Sales"].sum()

# Revenue %
df["Revenue_%"] = (df["Total_Sales"] / total_revenue) * 100

print(df[["Customer", "Total_Sales", "Revenue_%"]])

# Verify Revenue % sums to 100%
print("Revenue % Sum:", df["Revenue_%"].sum())

df_revenue = df.sort_values(
    "Total_Sales",
    ascending=False
).copy()

df_revenue["Cumulative_Revenue_%"] = (
    df_revenue["Revenue_%"].cumsum()
)

print(
    df_revenue[
        ["Customer", "Total_Sales", "Revenue_%", "Cumulative_Revenue_%"]
    ]
)

df_revenue["Pareto_Group"] = np.where(
    df_revenue["Cumulative_Revenue_%"] <= 80,
    "Top 80% Revenue Contributors",
    "Remaining Customers"
)

print(
    df_revenue[
        ["Customer", "Total_Sales", "Cumulative_Revenue_%", "Pareto_Group"]
    ]
)

top_3 = df_revenue.head(3)

top_3_revenue = top_3["Total_Sales"].sum()

top_3_percentage = (
    top_3_revenue / total_revenue
) * 100

remaining_revenue = total_revenue - top_3_revenue

print("Top 3 Revenue:", top_3_revenue)
print("Top 3 Revenue %:", top_3_percentage)
print("Remaining Revenue:", remaining_revenue)

df_profit = df.sort_values(
    "Total_Profit",
    ascending=False
).copy()

total_profit = df_profit["Total_Profit"].sum()

df_profit["Profit_%"] = (
    df_profit["Total_Profit"] / total_profit
) * 100

df_profit["Cumulative_Profit_%"] = (
    df_profit["Profit_%"].cumsum()
)

print(
    df_profit[
        [
            "Customer",
            "Total_Profit",
            "Profit_%",
            "Cumulative_Profit_%"
        ]
    ]
)

